{
  "table": "pos_sales",
  "columns": [
    {
      "target": "order_id",
      "source": ["order_no"],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 0.95,
      "note": "Maps receipt/order number to order_id"
    },
    {
      "target": "line_no",
      "source": ["items.line"],
      "transform": "int",
      "params": {
        "decimal": "."
      },
      "confidence": 0.95,
      "note": "Maps line number within order"
    },
    {
      "target": "sold_at",
      "source": ["created"],
      "transform": "datetime",
      "params": {
        "format": "%Y-%m-%dT%H:%M:%S"
      },
      "confidence": 0.95,
      "note": "Local date and time of the sale"
    },
    {
      "target": "store",
      "source": ["@export.store"],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 0.95,
      "note": "Store code from metadata"
    },
    {
      "target": "sku",
      "source": ["items.sku"],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 0.95,
      "note": "Product SKU code"
    },
    {
      "target": "qty",
      "source": ["items.qty"],
      "transform": "int",
      "params": {
        "decimal": "."
      },
      "confidence": 0.95,
      "note": "Quantity sold"
    },
    {
      "target": "unit_price",
      "source": ["items.price"],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 0.95,
      "note": "Unit price including tax"
    },
    {
      "target": "discount",
      "source": ["items.discount"],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 0.95,
      "note": "Discount applied to the line"
    },
    {
      "target": "line_total",
      "source": ["items.total"],
      "transform": "number",
      "params": {
        "decimal": "."
      },
      "confidence": 0.95,
      "note": "Line total charged"
    }
  ],
  "ignore": {
    "cashier": "Not present in pos_sales warehouse table schema",
    "items.#": "Item count per order is not part of the line item table structure"
  },
  "review": [
    "Check if cashier should be captured or if schema extension is needed.",
    "Verify store metadata matches correctly with store column."
  ]
}
